const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
let e = tok[1];
const INF = Infinity;
function mul(a, b) {
  const c = Array.from({ length: n }, () => new Array(n).fill(INF));
  for (let i = 0; i < n; i++) {
    for (let t = 0; t < n; t++) {
      const ait = a[i][t];
      if (ait === INF) continue;
      for (let j = 0; j < n; j++) {
        const v = ait + b[t][j];
        if (v < c[i][j]) c[i][j] = v;
      }
    }
  }
  return c;
}
let base = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => tok[2 + i * n + j] < 0 ? INF : tok[2 + i * n + j]));
let result = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => i === j ? 0 : INF));
while (e > 0) {
  if (e % 2 === 1) result = mul(result, base);
  base = mul(base, base);
  e = Math.floor(e / 2);
}
const r = result[0][n - 1];
console.log(r === INF ? '-1' : String(r));

