import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static final long INF = Long.MAX_VALUE / 4;
    static long[][] mul(long[][] a, long[][] b) {
        long[][] c = new long[n][n];
        for (long[] row : c) Arrays.fill(row, INF);
        for (int i = 0; i < n; i++)
            for (int t = 0; t < n; t++) {
                long ait = a[i][t];
                if (ait >= INF) continue;
                for (int j = 0; j < n; j++) {
                    if (b[t][j] >= INF) continue;
                    long v = ait + b[t][j];
                    if (v < c[i][j]) c[i][j] = v;
                }
            }
        return c;
    }
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        n = (int) st.nval;
        st.nextToken();
        long e = (long) st.nval;
        long[][] base = new long[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                st.nextToken();
                long w = (long) st.nval;
                base[i][j] = w < 0 ? INF : w;
            }
        long[][] result = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(result[i], INF);
            result[i][i] = 0;
        }
        while (e > 0) {
            if ((e & 1) == 1) result = mul(result, base);
            base = mul(base, base);
            e >>= 1;
        }
        long r = result[0][n - 1];
        System.out.println(r >= INF ? -1 : r);
    }
}

