#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF = LLONG_MAX / 4;
int n;
typedef vector<vector<ll>> Mat;
Mat mul(const Mat &a, const Mat &b) {
    Mat c(n, vector<ll>(n, INF));
    for (int i = 0; i < n; i++)
        for (int t = 0; t < n; t++) {
            if (a[i][t] >= INF) continue;
            for (int j = 0; j < n; j++) {
                if (b[t][j] >= INF) continue;
                c[i][j] = min(c[i][j], a[i][t] + b[t][j]);
            }
        }
    return c;
}
int main() {
    ll k;
    scanf("%d %lld", &n, &k);
    Mat base(n, vector<ll>(n)), result(n, vector<ll>(n, INF));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            ll w;
            scanf("%lld", &w);
            base[i][j] = w < 0 ? INF : w;
        }
    for (int i = 0; i < n; i++) result[i][i] = 0;
    while (k > 0) {
        if (k & 1) result = mul(result, base);
        base = mul(base, base);
        k >>= 1;
    }
    ll r = result[0][n - 1];
    printf("%lld\n", r >= INF ? -1LL : r);
    return 0;
}
